import 'package:uuid/uuid.dart';
import 'priority.dart';
import 'recurrence.dart';
import 'task.dart';

/// Represents a structured reminder suggestion generated by the AI assistant before confirmation.
class AiReminderDraft {
  final String? id;
  final String title;
  final String description;
  final DateTime dueDate;
  final int dueHour;
  final int dueMinute;
  final Priority priority;
  final Recurrence recurrence;
  final String? url;
  final List<String> channels;
  final String? reasoning;
  final String rawPrompt;

  const AiReminderDraft({
    this.id,
    required this.title,
    this.description = '',
    required this.dueDate,
    required this.dueHour,
    required this.dueMinute,
    this.priority = Priority.medium,
    this.recurrence = Recurrence.none,
    this.url,
    this.channels = const ['local', 'whatsapp'],
    this.reasoning,
    required this.rawPrompt,
  });

  String get draftId =>
      (id != null && id!.isNotEmpty) ? id! : '${title}_${dueDate.millisecondsSinceEpoch}_${dueHour}_$dueMinute';

  /// Bridges this AI draft into an immutable [Task] ready for persistence and notification scheduling.
  Task toTask({String? id, DateTime? createdAt, DateTime? updatedAt}) {
    final now = DateTime.now();
    return Task(
      id: id ?? this.id ?? const Uuid().v4(),
      title: title,
      description: description,
      dueDate: dueDate,
      dueHour: dueHour,
      dueMinute: dueMinute,
      priority: priority,
      recurrence: recurrence,
      url: url,
      channels: channels,
      isNotificationEnabled: true,
      isCompleted: false,
      createdAt: createdAt ?? now,
      updatedAt: updatedAt ?? createdAt ?? now,
    );
  }

  /// Returns a copy of this draft with the given fields replaced.
  AiReminderDraft copyWith({
    String? id,
    String? title,
    String? description,
    DateTime? dueDate,
    int? dueHour,
    int? dueMinute,
    Priority? priority,
    Recurrence? recurrence,
    String? url,
    List<String>? channels,
    String? reasoning,
    String? rawPrompt,
  }) {
    return AiReminderDraft(
      id: id ?? this.id,
      title: title ?? this.title,
      description: description ?? this.description,
      dueDate: dueDate ?? this.dueDate,
      dueHour: dueHour ?? this.dueHour,
      dueMinute: dueMinute ?? this.dueMinute,
      priority: priority ?? this.priority,
      recurrence: recurrence ?? this.recurrence,
      url: url ?? this.url,
      channels: channels ?? this.channels,
      reasoning: reasoning ?? this.reasoning,
      rawPrompt: rawPrompt ?? this.rawPrompt,
    );
  }

  Map<String, dynamic> toJson() => {
        if (id != null) 'id': id,
        'title': title,
        'description': description,
        'dueDate':
            '${dueDate.year.toString().padLeft(4, '0')}-${dueDate.month.toString().padLeft(2, '0')}-${dueDate.day.toString().padLeft(2, '0')}',
        'dueHour': dueHour,
        'dueMinute': dueMinute,
        'priority': priority.name,
        'recurrence': recurrence.name,
        'url': url,
        'channels': channels,
        'reasoning': reasoning,
        'rawPrompt': rawPrompt,
      };

  factory AiReminderDraft.fromJson(Map<String, dynamic> json) {
    final dueDateRaw = (json['dueDate'] ?? json['due_date']) as String?;
    DateTime parsedDate;
    if (dueDateRaw != null && dueDateRaw.isNotEmpty) {
      parsedDate = DateTime.tryParse(dueDateRaw) ?? DateTime.now();
    } else {
      parsedDate = DateTime.now();
    }

    final rawDueHour = json['dueHour'] ?? json['due_hour'];
    final parsedDueHour = rawDueHour is int
        ? rawDueHour
        : (rawDueHour != null ? int.tryParse(rawDueHour.toString()) : null);

    final rawDueMinute = json['dueMinute'] ?? json['due_minute'];
    final parsedDueMinute = rawDueMinute is int
        ? rawDueMinute
        : (rawDueMinute != null ? int.tryParse(rawDueMinute.toString()) : null);

    final draftId = (json['id'] as String?)?.trim();

    return AiReminderDraft(
      id: (draftId != null && draftId.isNotEmpty) ? draftId : const Uuid().v4(),
      title: json['title'] as String? ?? '',
      description: json['description'] as String? ?? '',
      dueDate: parsedDate,
      dueHour: parsedDueHour ?? 9,
      dueMinute: parsedDueMinute ?? 0,
      priority: Priority.fromString(json['priority'] as String?),
      recurrence: Recurrence.fromString(json['recurrence'] as String?),
      url: json['url'] as String?,
      channels: json['channels'] != null
          ? List<String>.from(json['channels'] as List)
          : const ['local', 'whatsapp'],
      reasoning: json['reasoning'] as String?,
      rawPrompt: (json['rawPrompt'] ?? json['raw_prompt']) as String? ?? '',
    );
  }
}
